  double get TOTAL_VALUE => const fb.Float64Reader().vTableGet(_bc, _bcOffset, 20, 0.0);
  double get totalValue => TOTAL_VALUE;
  ///  Problems met, one per line, e.g. "ETH: lookup incomplete"; empty when
  ///  ATTESTED.
  List<String>? get ERRORS => const fb.ListReader<String>(fb.StringReader()).vTableGetNullable(_bc, _bcOffset, 22);
  ///  Unix milliseconds the holdings were read (the as-of time); 0 in a
  ///  request.
  int get AS_OF_MS => const fb.Int64Reader().vTableGet(_bc, _bcOffset, 24, 0);
  int get asOfMs => AS_OF_MS;
  ///  Identifier of the attester (a peer identifier or module identifier).
  String? get ATTESTER_ID => const fb.StringReader().vTableGetNullable(_bc, _bcOffset, 26);
  String? get attesterId => ATTESTER_ID;
  ///  Attester's signature over the attestation, and its scheme (e.g.
  ///  "ed25519"); empty when unsigned.
  List<int>? get SIGNATURE => const fb.Uint8ListReader().vTableGetNullable(_bc, _bcOffset, 28);
  String? get SIGNATURE_TYPE => const fb.StringReader().vTableGetNullable(_bc, _bcOffset, 30);
  String? get signatureType => SIGNATURE_TYPE;

  @override
  String toString() {
    return 'WHA{attestationId: ${attestationId}, subjectId: ${subjectId}, PURPOSE: ${PURPOSE}, ACCOUNTS: ${ACCOUNTS}, HOLDINGS: ${HOLDINGS}, CHAINS: ${CHAINS}, CURRENCY: ${CURRENCY}, ATTESTED: ${ATTESTED}, totalValue: ${totalValue}, ERRORS: ${ERRORS}, asOfMs: ${asOfMs}, attesterId: ${attesterId}, SIGNATURE: ${SIGNATURE}, signatureType: ${signatureType}}';
  }
}

class _WHAReader extends fb.TableReader<WHA> {
  const _WHAReader();

  @override
  WHA createObject(fb.BufferContext bc, int offset) =>
    WHA._(bc, offset);
}

class WHABuilder {
  WHABuilder(this.fbBuilder);

  final fb.Builder fbBuilder;

  void begin() {
    fbBuilder.startTable(14);
  }

  int addAttestationIdOffset(int? offset) {
    fbBuilder.addOffset(0, offset);
    return fbBuilder.offset;
  }
  int addSubjectIdOffset(int? offset) {
    fbBuilder.addOffset(1, offset);
    return fbBuilder.offset;
  }
  int addPurposeOffset(int? offset) {
    fbBuilder.addOffset(2, offset);
    return fbBuilder.offset;
  }
  int addAccountsOffset(int? offset) {
    fbBuilder.addOffset(3, offset);
    return fbBuilder.offset;
  }
  int addHoldingsOffset(int? offset) {
    fbBuilder.addOffset(4, offset);
    return fbBuilder.offset;
  }
  int addChainsOffset(int? offset) {
    fbBuilder.addOffset(5, offset);
    return fbBuilder.offset;
  }
  int addCurrencyOffset(int? offset) {
    fbBuilder.addOffset(6, offset);
    return fbBuilder.offset;
  }
  int addAttested(bool? ATTESTED) {
    fbBuilder.addBool(7, ATTESTED);
    return fbBuilder.offset;
  }
  int addTotalValue(double? TOTAL_VALUE) {
    fbBuilder.addFloat64(8, TOTAL_VALUE);
    return fbBuilder.offset;
  }
  int addErrorsOffset(int? offset) {
    fbBuilder.addOffset(9, offset);
    return fbBuilder.offset;
  }
  int addAsOfMs(int? AS_OF_MS) {
    fbBuilder.addInt64(10, AS_OF_MS);
    return fbBuilder.offset;
  }
  int addAttesterIdOffset(int? offset) {
    fbBuilder.addOffset(11, offset);
    return fbBuilder.offset;
  }
  int addSignatureOffset(int? offset) {
    fbBuilder.addOffset(12, offset);
    return fbBuilder.offset;
  }
  int addSignatureTypeOffset(int? offset) {
    fbBuilder.addOffset(13, offset);
    return fbBuilder.offset;
  }

  int finish() {
    return fbBuilder.endTable();
  }
}

class WHAObjectBuilder extends fb.ObjectBuilder {
  final String? _ATTESTATION_ID;
  final String? _SUBJECT_ID;
  final String? _PURPOSE;
  final List<WHAAccountObjectBuilder>? _ACCOUNTS;
  final List<WHAHoldingObjectBuilder>? _HOLDINGS;
  final List<WHAChainObjectBuilder>? _CHAINS;
  final String? _CURRENCY;
  final bool? _ATTESTED;
  final double? _TOTAL_VALUE;
  final List<String>? _ERRORS;
  final int? _AS_OF_MS;
  final String? _ATTESTER_ID;
  final List<int>? _SIGNATURE;
  final String? _SIGNATURE_TYPE;

  WHAObjectBuilder({
    String? ATTESTATION_ID,
    String? attestationId,
    String? SUBJECT_ID,
    String? subjectId,
    String? PURPOSE,
    List<WHAAccountObjectBuilder>? ACCOUNTS,
    List<WHAHoldingObjectBuilder>? HOLDINGS,
    List<WHAChainObjectBuilder>? CHAINS,
    String? CURRENCY,
    bool? ATTESTED,
    double? TOTAL_VALUE,
    double? totalValue,
    List<String>? ERRORS,
    int? AS_OF_MS,
    int? asOfMs,
    String? ATTESTER_ID,
    String? attesterId,
    List<int>? SIGNATURE,
    String? SIGNATURE_TYPE,
    String? signatureType,
  })
      : _ATTESTATION_ID = attestationId ?? ATTESTATION_ID,
        _SUBJECT_ID = subjectId ?? SUBJECT_ID,
        _PURPOSE = PURPOSE,
        _ACCOUNTS = ACCOUNTS,
        _HOLDINGS = HOLDINGS,
        _CHAINS = CHAINS,
        _CURRENCY = CURRENCY,
        _ATTESTED = ATTESTED,
        _TOTAL_VALUE = totalValue ?? TOTAL_VALUE,
        _ERRORS = ERRORS,
        _AS_OF_MS = asOfMs ?? AS_OF_MS,
        _ATTESTER_ID = attesterId ?? ATTESTER_ID,
        _SIGNATURE = SIGNATURE,
        _SIGNATURE_TYPE = signatureType ?? SIGNATURE_TYPE;

  /// Finish building, and store into the [fbBuilder].
  @override
  int finish(fb.Builder fbBuilder) {
    final int? ATTESTATION_IDOffset = _ATTESTATION_ID == null ? null
        : fbBuilder.writeString(_ATTESTATION_ID!);
    final int? SUBJECT_IDOffset = _SUBJECT_ID == null ? null
        : fbBuilder.writeString(_SUBJECT_ID!);
    final int? PURPOSEOffset = _PURPOSE == null ? null
        : fbBuilder.writeString(_PURPOSE!);
    final int? ACCOUNTSOffset = _ACCOUNTS == null ? null
        : fbBuilder.writeList(_ACCOUNTS!.map((b) => b.getOrCreateOffset(fbBuilder)).toList());
    final int? HOLDINGSOffset = _HOLDINGS == null ? null
        : fbBuilder.writeList(_HOLDINGS!.map((b) => b.getOrCreateOffset(fbBuilder)).toList());
    final int? CHAINSOffset = _CHAINS == null ? null
        : fbBuilder.writeList(_CHAINS!.map((b) => b.getOrCreateOffset(fbBuilder)).toList());
    final int? CURRENCYOffset = _CURRENCY == null ? null
        : fbBuilder.writeString(_CURRENCY!);
    final int? ERRORSOffset = _ERRORS == null ? null
        : fbBuilder.writeList(_ERRORS!.map(fbBuilder.writeString).toList());
    final int? ATTESTER_IDOffset = _ATTESTER_ID == null ? null
        : fbBuilder.writeString(_ATTESTER_ID!);
    final int? SIGNATUREOffset = _SIGNATURE == null ? null
        : fbBuilder.writeListUint8(_SIGNATURE!);
    final int? SIGNATURE_TYPEOffset = _SIGNATURE_TYPE == null ? null
        : fbBuilder.writeString(_SIGNATURE_TYPE!);
    fbBuilder.startTable(14);
    fbBuilder.addOffset(0, ATTESTATION_IDOffset);
    fbBuilder.addOffset(1, SUBJECT_IDOffset);
    fbBuilder.addOffset(2, PURPOSEOffset);
    fbBuilder.addOffset(3, ACCOUNTSOffset);
    fbBuilder.addOffset(4, HOLDINGSOffset);
    fbBuilder.addOffset(5, CHAINSOffset);
    fbBuilder.addOffset(6, CURRENCYOffset);
    fbBuilder.addBool(7, _ATTESTED);
    fbBuilder.addFloat64(8, _TOTAL_VALUE);
    fbBuilder.addOffset(9, ERRORSOffset);
    fbBuilder.addInt64(10, _AS_OF_MS);
    fbBuilder.addOffset(11, ATTESTER_IDOffset);
    fbBuilder.addOffset(12, SIGNATUREOffset);
    fbBuilder.addOffset(13, SIGNATURE_TYPEOffset);
    return fbBuilder.endTable();
  }

  /// Convenience method to serialize to byte list.
  @override
  Uint8List toBytes([String? fileIdentifier]) {
    final fbBuilder = fb.Builder(deduplicateTables: false);
    fbBuilder.finish(finish(fbBuilder), fileIdentifier);
    return fbBuilder.buffer;
  }
}
